package main

const page = `<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="google" content="notranslate"><title>MThanglee KeyGen</title>
<style>
:root{--bg:#10141b;--panel:#191f29;--panel2:#232b38;--line:#333e4e;--fg:#edf1f6;--mut:#9fabba;--acc:#ffa31a;--on:#241200;--bad:#ff9d9b;--good:#7ddc9c}
*{box-sizing:border-box}html,body{height:100%;margin:0}body{background:var(--bg);color:var(--fg);font:14px/1.5 "Segoe UI Variable Text","Segoe UI",system-ui,sans-serif}
button,input,select,textarea{font:inherit;color:inherit}button{background:var(--panel2);border:1px solid var(--line);border-radius:6px;padding:7px 13px;cursor:pointer}button:hover{border-color:var(--acc)}button.pri{background:var(--acc);border-color:var(--acc);color:var(--on);font-weight:700}
input,select,textarea{background:var(--panel2);border:1px solid var(--line);border-radius:6px;padding:7px 9px;width:100%;min-width:0}textarea{font:12.5px Consolas,monospace;min-height:84px;resize:vertical}
:focus-visible{outline:2px solid var(--acc);outline-offset:1px}
.center{min-height:100%;display:grid;place-items:center;padding:16px}.card{background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:24px;width:min(460px,100%)}
h1{font-size:20px;margin:0 0 4px}h2{font-size:15px;margin:0 0 10px}p{color:var(--mut);margin:4px 0 12px;font-size:13.5px}label{display:block;font-size:12.5px;color:var(--mut);margin:10px 0 3px}
.err{color:var(--bad);min-height:20px;font-size:13px;margin-top:8px}.row{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}.grow{flex:1}
header{display:flex;align-items:center;gap:6px;padding:10px 16px;background:var(--panel);border-bottom:1px solid var(--line);flex-wrap:wrap}header b{margin-right:14px;font-size:15px}header button{border-color:transparent;background:none;color:var(--mut)}header button[aria-selected=true]{color:var(--fg);box-shadow:inset 0 -2px 0 var(--acc);border-radius:0}.sp{flex:1}
main{padding:16px;max-width:980px;margin:0 auto}.grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:16px}@media(max-width:760px){.grid{grid-template-columns:minmax(0,1fr)}}.box{background:var(--panel);border:1px solid var(--line);border-radius:10px;padding:16px;min-width:0}
.check{display:flex;gap:8px;align-items:center;color:var(--fg);font-size:13.5px;margin-top:10px}.check input{width:16px;height:16px;accent-color:var(--acc)}
.warn{color:#ffcf8a;font-size:13px}.mono{font:12.5px Consolas,monospace;word-break:break-all;background:var(--panel2);padding:8px;border-radius:6px;border:1px solid var(--line)}
.tw{overflow:auto}table{border-collapse:collapse;width:100%;font-size:13px}th{color:var(--mut);text-align:left;font-weight:600}td,th{padding:7px 8px;border-bottom:1px solid var(--line);white-space:nowrap}td.k{max-width:220px;overflow:hidden;text-overflow:ellipsis;font-family:Consolas,monospace;font-size:12px}
ol{margin:6px 0 0;padding-left:20px;color:var(--mut);font-size:13.5px}
</style></head><body><div id="root"></div>
<script>
"use strict";
const R=document.getElementById('root');let st={},tab='make',last=[];
const api=async(u,b)=>{const r=await fetch(u,b===undefined?{}:{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(b)});const j=await r.json();if(!r.ok)throw new Error(j.error||'Có lỗi xảy ra.');return j};
const esc=s=>String(s==null?'':s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const copy=async(t,b)=>{try{await navigator.clipboard.writeText(t);const o=b.textContent;b.textContent='Đã chép';setTimeout(()=>b.textContent=o,1400)}catch(e){b.textContent='Hãy tự chọn rồi Ctrl+C'}};
async function load(){st=await api('/api/state');draw()}
function draw(){if(!st.setup)return setup();if(!st.unlocked)return lock();shell()}
function setup(){R.innerHTML='<div class=center><div class=card><h1>MThanglee KeyGen</h1><p>Lần đầu dùng: đặt mật khẩu để tạo bộ khóa ký key. Khóa bí mật chỉ nằm trên máy này. Mất cả mật khẩu lẫn file sao lưu thì không tạo được key mới.</p><label for=p1>Mật khẩu, ít nhất 8 ký tự</label><input id=p1 type=password autofocus><label for=p2>Nhập lại mật khẩu</label><input id=p2 type=password><div class=err id=e></div><div class=row><button class="pri grow" id=go>Tạo bộ khóa</button><button id=rs>Khôi phục từ bản sao lưu</button></div><input id=f type=file accept=.json hidden></div></div>';
 go.onclick=async()=>{e.textContent='';if(p1.value!==p2.value){e.textContent='Hai mật khẩu chưa khớp.';return}go.disabled=true;go.textContent='Đang tạo…';try{await api('/api/setup',{password:p1.value});tab='vault';await load()}catch(x){e.textContent=x.message;go.disabled=false;go.textContent='Tạo bộ khóa'}};
 rs.onclick=()=>f.click();f.onchange=async()=>{const t=await f.files[0].text();if(p1.value.length<1){e.textContent='Nhập mật khẩu của bản sao lưu vào ô trên rồi chọn lại file.';f.value='';return}try{await api('/api/restore',{backup:t,password:p1.value});await load()}catch(x){e.textContent=x.message}f.value=''}}
function lock(){R.innerHTML='<div class=center><div class=card><h1>MThanglee KeyGen</h1><p>Nhập mật khẩu để mở bộ khóa.</p><form id=fm><label for=p1>Mật khẩu</label><input id=p1 type=password autofocus><div class=err id=e></div><div class=row><button class="pri grow" id=go>Mở khóa</button></div></form></div></div>';
 fm.onsubmit=async v=>{v.preventDefault();go.disabled=true;e.textContent='';try{await api('/api/unlock',{password:p1.value});await load()}catch(x){e.textContent=x.message;go.disabled=false}}}
function shell(){R.innerHTML='<header><b>MThanglee KeyGen</b><button role=tab data-t=make>Tạo key</button><button role=tab data-t=hist>Lịch sử ('+st.count+')</button><button role=tab data-t=vault>Khóa &amp; sao lưu</button><span class=sp></span><button id=lk>Khóa app</button></header><main id=m></main>';
 document.querySelectorAll('[data-t]').forEach(b=>{b.setAttribute('aria-selected',b.dataset.t===tab);b.onclick=()=>{tab=b.dataset.t;shell()}});lk.onclick=async()=>{await api('/api/lock',{});await load()};
 ({make,hist,vault})[tab]()}
function make(){m.innerHTML='<div class=grid><div class=box><h2>Thông tin khách</h2><label for=n>Tên khách</label><input id=n placeholder="Ví dụ: Studio An Nhiên"><label for=mc>Mã máy khách gửi</label><input id=mc placeholder="ABCD-EFGH-IJKLM"><label class=check><input type=checkbox id=any> Key dùng cho mọi máy</label><p class=warn id=aw hidden>Key mọi máy có thể chia sẻ cho người khác. Chỉ dùng khi cần.</p><div id=qr hidden><label for=q>Số lượng key</label><input id=q type=number min=1 max=200 value=1></div><label for=d>Thời hạn</label><select id=d><option value=0>Vĩnh viễn</option><option value=30>30 ngày</option><option value=90>90 ngày</option><option value=180>180 ngày</option><option value=365 selected>1 năm</option><option value=730>2 năm</option><option value=-1>Tự nhập số ngày</option></select><div id=cr hidden><label for=c>Số ngày</label><input id=c type=number min=1 value=7></div><label for=nt>Ghi chú</label><input id=nt placeholder="Không bắt buộc"><div class=err id=e></div><div class=row><button class="pri grow" id=go>Tạo key</button></div></div><div class=box><h2>Key vừa tạo</h2><div id=out><p>Key sẽ hiện ở đây.</p></div></div></div>';
 any.onchange=()=>{aw.hidden=qr.hidden=!any.checked;mc.disabled=any.checked};d.onchange=()=>cr.hidden=d.value!=='-1';
 go.onclick=async()=>{e.textContent='';const days=d.value==='-1'?+c.value:+d.value;if(!(days>=0)){e.textContent='Số ngày chưa đúng.';return}try{const r=await api('/api/issue',{name:n.value,machine:mc.value,any:any.checked,days,qty:+q.value||1,note:nt.value});st.count+=r.keys.length;show(r.keys);document.querySelector('[data-t=hist]').textContent='Lịch sử ('+st.count+')'}catch(x){e.textContent=x.message}}}
function show(ks){out.innerHTML='<p>'+esc(ks[0].name||'Khách')+' · '+esc(ks[0].machine)+' · Hạn: '+esc(ks[0].expires)+'</p><textarea id=kt readonly aria-label="Key vừa tạo">'+esc(ks.map(k=>k.key).join('\n'))+'</textarea><div class=row><button class=pri id=cp>Sao chép key</button></div>';cp.onclick=e=>copy(kt.value,e.target)}
async function hist(){const h=await api('/api/history');m.innerHTML='<div class=box><div class=row style="margin:0 0 10px"><input id=s placeholder="Tìm theo tên, mã máy, ghi chú" class=grow style="flex:1;width:auto"><button id=csv>Xuất CSV</button></div><div class=tw><table><thead><tr><th>Ngày tạo</th><th>Khách</th><th>Mã máy</th><th>Hạn</th><th>Ghi chú</th><th>Key</th><th></th></tr></thead><tbody id=tb></tbody></table></div></div>';
 const paint=()=>{const q=s.value.toLowerCase(),l=h.filter(x=>(x.name+x.machine+x.note).toLowerCase().includes(q));tb.innerHTML=l.map((x,i)=>'<tr><td>'+esc(x.time)+'</td><td>'+esc(x.name)+'</td><td>'+esc(x.machine)+'</td><td>'+esc(x.expires)+'</td><td>'+esc(x.note)+'</td><td class=k>'+esc(x.key)+'</td><td><button data-i='+h.indexOf(x)+'>Chép</button></td></tr>').join('')||'<tr><td colspan=7>Chưa có key.</td></tr>';tb.querySelectorAll('button').forEach(b=>b.onclick=()=>copy(h[+b.dataset.i].key,b))};s.oninput=paint;paint();
 csv.onclick=()=>{const q=v=>'"'+String(v||'').replace(/"/g,'""')+'"',t='\ufeffNgày tạo,Khách,Mã máy,Hạn,Ghi chú,Key\n'+h.map(x=>[x.time,x.name,x.machine,x.expires,x.note,x.key].map(q).join(',')).join('\n'),a=document.createElement('a');a.href=URL.createObjectURL(new Blob([t],{type:'text/csv'}));a.download='MThanglee_lich_su_key.csv';a.click()}}
function vault(){m.innerHTML='<div class=grid><div class=box><h2>Khóa công khai</h2><p>Dán chuỗi này vào app trước khi build.</p><div class=mono id=pk>'+esc(st.pub)+'</div><div class=row><button class=pri id=cp>Sao chép khóa công khai</button></div><ol><li>Trên GitHub mở file app/photosift/license_pub.py.</li><li>Bấm biểu tượng bút chì để sửa.</li><li>Dán vào giữa hai dấu ngoặc kép của dòng PUB_HEX, rồi Commit.</li></ol></div><div class=box><h2>Sao lưu khóa bí mật</h2><p>Tải file này và cất ở nơi an toàn ngoài máy, như USB riêng. File đã mã hóa bằng mật khẩu của bạn. Mất khóa thì không tạo được key mới cho bản đã phát hành.</p><div class=row><a id=dl href=/api/backup download><button class=pri>Tải file sao lưu</button></a></div><p class=warn style="margin-top:12px">Không gửi file này hay mật khẩu cho ai. Không đưa file này lên GitHub.</p></div></div>';cp.onclick=e=>copy(st.pub,e.target)}
load();
</script></body></html>`
